UPDATE t_pla_acc_sesion SET token_valido = 'N' WHERE id_usuario = :IdUsuario AND id_canal = :IdCanal AND token_valido = 'S' AND ( SELECT valor AS "Valor" FROM t_pla_pla_configuracion WHERE codigo_parametro = 'PLA.SesionUnicaUsuario' ) = 'S' AND EXISTS ( SELECT 1 FROM t_pla_pla_configuracion c WHERE c.codigo_parametro = 'PLA.CanalesSesionUnica' AND ';' || c.valor || ';' LIKE '%;' || id_canal || ';%' )